    settings = merge.load_settings(ctx.data / "settings.json")
    keep = merge.load_keep_apart(ctx.data / "keep_apart.csv")
    members = ctx.members
    groups, refused = merge.plan(members, ctx.aliases, settings, keep, ctx.stamp)
    out = []
    entries = []
    seq = audit.next_seq(ctx.entries)
    for g in groups:
        s, ms = ids.fmt(g["survivor"]), [ids.fmt(n) for n in g["merged"]]
        out.append(f"merge {s} <- {', '.join(ms)} ({', '.join(g['rules'])})")
        for f, (b, af) in g["changes"].items():
            out.append(f"  {f}: {merge.jd(b)} -> {merge.jd(af)}")
        entries.append({"seq": seq, "at": ctx.stamp, "op": "merge", "by": ctx.by, "member": s, "merged": ms,
                        "rules": g["rules"], "changes": g["changes"], "from": g["from"]})
        seq += 1
    for x, y, rule in refused:
        out.append(f"kept apart {ids.fmt(x)} {ids.fmt(y)} ({rule})")
    out.append(f"{len(groups)} groups, {sum(len(g['merged']) for g in groups)} members merged, {len(refused)} pairs kept apart")
    if not a.apply:
        out.append("dry run: nothing written")
    elif groups:
        gone = {}
        for g in groups:
            for n in g["merged"]:
                gone[n] = g["survivor"]
        register = {n: r for n, r in members.items() if n not in gone}
        for g in groups:
            register[g["survivor"]] = g["record"]
        amap = {k: gone.get(v, v) for k, v in ctx.aliases.items()}
        amap.update(gone)
        rows = []
        for r in ctx.payments:
            n = ids.number(r["member"])
            if n is not None:
                m = aliases.resolve(ctx.aliases, n)
                if m in gone:
                    r = {**r, "member": ids.fmt(gone[m])}
            rows.append(r)
        ctx.commit(register=register, alias_map=amap, payment_rows=rows, new_entries=entries)
    return out


def build_parser()''')
